package cn.nebulaedata.cccs.nebuwork.backend.api.agent;
import cn.nebulaedata.cccs.nebuwork.backend.api.platformmcp.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.test.context.TestPropertySource;
import java.util.*;
import static cn.nebulaedata.cccs.nebuwork.backend.api.common.ApiSupport.map;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@TestPropertySource(properties={"nebu.platform-mcp.url=http://platform.invalid/mcp","nebu.platform-mcp.service-key=platform-service-key-12345678901234567890"})
class PlatformMcpIntegrationTest extends AgentIntegrationTest {
    @Autowired PlatformMcpCatalog catalog;
    @Autowired PlatformMcpService platform;
    String token,rootTask,wbId,projectId;ObjectNode identity;
    void enable(String scope,String... tools)throws Exception{
        wbId=workbench();projectId=project(wbId);
        JsonNode policy=json.valueToTree(map("enabled",true,"scope",scope,"tools",Arrays.asList(tools),"resources",Collections.emptyList()));
        data(postJson("/api/workbenches/"+wbId+"/platform-mcp-policy",map("revision",0,"policy",policy)),"alice");
        data(postJson("/api/workbenches/"+wbId+"/platform-mcp-policy/publish",map("revision",1)),"alice");
        JsonNode task=data(postJson("/api/projects/"+projectId+"/tasks",map("content","MCP test")).header("Idempotency-Key",UUID.randomUUID().toString()),"alice");rootTask=task.path("task").path("id").asText();ObjectNode run=(ObjectNode)remoteRuns.values().iterator().next();
        identity=json.valueToTree(map("ownerId","alice","projectId",projectId,"tenantId","nebuwork-v2","sessionId",run.path("sessionId").asText(),"runId",run.path("id").asText(),"taskId",rootTask));
        run.set("manifest",json.valueToTree(bridge.context(identity)));run.put("manifestHash","test-manifest");identity.put("manifestHash","test-manifest");
        token=json.valueToTree(platform.grant(identity)).path("token").asText();
    }
    JsonNode call(String name,Object args,String call)throws Exception{return json.readTree(mvc.perform(postJson("/internal/platform-mcp/execute",map("name",name,"arguments",args,"callId",call)).header("Authorization","Bearer platform-service-key-12345678901234567890").header("X-Platform-Mcp-Grant",token)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8));}
    @Test void catalogIsStrictAndDoesNotExposeHumanOrMissingOperations(){assertTrue(catalog.all().size()>150);assertThrows(RuntimeException.class,()->catalog.get("nw_memory_approve"));assertThrows(RuntimeException.class,()->catalog.get("nw_intelligence_collect"));for(PlatformMcpCatalog.Tool t:catalog.all()){assertTrue(t.name.matches("nw_[a-z_]+"));assertEquals(false,t.schema.get("additionalProperties"));}assertThrows(RuntimeException.class,()->catalog.validate(catalog.get("nw_identity_get"),json.valueToTree(map("ownerId","bob"))));}
    @Test void policyOwnershipAndRevisionsAreEnforced()throws Exception{String wb=workbench();mvc.perform(get("/api/workbenches/"+wb+"/platform-mcp-policy").header("token","bob-token")).andExpect(status().isNotFound());mvc.perform(postJson("/api/workbenches/"+wb+"/platform-mcp-policy",map("revision",4,"policy",map())).header("token","alice-token")).andExpect(status().isConflict());}
    @Test void localWritesAreAtomicAndReplayedAcrossFreshContexts()throws Exception{enable("current_project","nw_project_save","nw_project_get");Map<String,Object> args=map("mode","update","id",projectId,"data",map("revision",1,"name","MCP renamed"));JsonNode first=call("nw_project_save",args,"stable-call"),again=call("nw_project_save",args,"stable-call");assertEquals(first,again);assertEquals(2,data(get("/api/projects/"+projectId),"alice").path("project").path("revision").asInt());mvc.perform(postJson("/internal/platform-mcp/execute",map("name","nw_project_save","arguments",map("mode","update","id",projectId,"data",map("revision",2,"name","different")),"callId","stable-call")).header("Authorization","Bearer platform-service-key-12345678901234567890").header("X-Platform-Mcp-Grant",token)).andExpect(status().isConflict());}
    @Test void lostTaskResponsesRecoverTheOriginalBusinessTaskWithoutResubmission()throws Exception{enable("account","nw_task_create");JsonNode result=call("nw_task_create",map("projectId",projectId,"data",map("title","原操作任务")),"lost-response");String operation=result.path("operationId").asText(),target=result.path("data").path("task").path("id").asText();jdbc.update("UPDATE nw_platform_mcp_call SET state='unknown',result_json=NULL WHERE id=?",operation);ObjectNode request=identity.deepCopy();request.put("name","nw_task_create");request.put("callId","lost-response");JsonNode recovered=json.valueToTree(platform.reconcileAgent(request));assertEquals("completed",recovered.path("status").asText());assertEquals(target,recovered.path("result").path("data").path("task").path("id").asText());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM nw_agent_task WHERE id=?",Integer.class,target));}
    @Test void revokedPoliciesDenyEvenPreviouslyCompletedReads()throws Exception{enable("current_project","nw_identity_get");assertEquals("alice",call("nw_identity_get",map(),"read-one").path("data").path("ownerId").asText());data(postJson("/api/workbenches/"+wbId+"/platform-mcp-policy/revoke",map("revision",1)),"alice");mvc.perform(postJson("/internal/platform-mcp/execute",map("name","nw_identity_get","arguments",map(),"callId","read-one")).header("Authorization","Bearer platform-service-key-12345678901234567890").header("X-Platform-Mcp-Grant",token)).andExpect(status().isForbidden());}
    @Test void currentProjectScopeCannotReadAnotherOwnedProject()throws Exception{enable("current_project","nw_project_get");String other=project(wbId);mvc.perform(postJson("/internal/platform-mcp/execute",map("name","nw_project_get","arguments",map("id",other),"callId","scope-test")).header("Authorization","Bearer platform-service-key-12345678901234567890").header("X-Platform-Mcp-Grant",token)).andExpect(status().isForbidden());}
    @Test void accountScopeStillRequiresBusinessOwnership()throws Exception{enable("account","nw_project_get");String other=project(wbId);jdbc.update("UPDATE nw_project SET owner_id='bob' WHERE id=?",other);mvc.perform(postJson("/internal/platform-mcp/execute",map("name","nw_project_get","arguments",map("id",other),"callId","cross-account")).header("Authorization","Bearer platform-service-key-12345678901234567890").header("X-Platform-Mcp-Grant",token)).andExpect(status().isNotFound());}
    @Test void expandingCurrentPolicyCannotExpandAnExistingSnapshot()throws Exception{enable("current_project","nw_project_get");String other=project(wbId);Object policy=map("enabled",true,"scope","account","tools",Arrays.asList("nw_project_get"),"resources",Collections.emptyList());data(postJson("/api/workbenches/"+wbId+"/platform-mcp-policy",map("revision",1,"policy",policy)),"alice");data(postJson("/api/workbenches/"+wbId+"/platform-mcp-policy/publish",map("revision",2)),"alice");mvc.perform(postJson("/internal/platform-mcp/execute",map("name","nw_project_get","arguments",map("id",other),"callId","no-expansion")).header("Authorization","Bearer platform-service-key-12345678901234567890").header("X-Platform-Mcp-Grant",token)).andExpect(status().isForbidden());}
    @Test void republishingDoesNotReviveRevokedRuns()throws Exception{enable("current_project","nw_identity_get");data(postJson("/api/workbenches/"+wbId+"/platform-mcp-policy/revoke",map("revision",1)),"alice");Object policy=map("enabled",true,"scope","current_project","tools",Arrays.asList("nw_identity_get"),"resources",Collections.emptyList());data(postJson("/api/workbenches/"+wbId+"/platform-mcp-policy",map("revision",2,"policy",policy)),"alice");data(postJson("/api/workbenches/"+wbId+"/platform-mcp-policy/publish",map("revision",3)),"alice");mvc.perform(postJson("/internal/platform-mcp/execute",map("name","nw_identity_get","arguments",map(),"callId","revoked-run")).header("Authorization","Bearer platform-service-key-12345678901234567890").header("X-Platform-Mcp-Grant",token)).andExpect(status().isForbidden());}
    @Test void serviceAuthenticationAndManifestAreBothRequired()throws Exception{enable("current_project","nw_identity_get");mvc.perform(postJson("/internal/platform-mcp/context",map()).header("X-Platform-Mcp-Grant",token)).andExpect(status().isUnauthorized());ObjectNode run=(ObjectNode)remoteRuns.values().iterator().next();run.put("manifestHash","changed");mvc.perform(postJson("/internal/platform-mcp/context",map()).header("Authorization","Bearer platform-service-key-12345678901234567890").header("X-Platform-Mcp-Grant",token)).andExpect(status().isForbidden());}
    @Test void delegatedRunsCannotUseAccountCreationPrivileges()throws Exception{enable("account","nw_workbench_save");((ObjectNode)remoteRuns.values().iterator().next()).put("parentRunId","root");mvc.perform(postJson("/internal/platform-mcp/execute",map("name","nw_workbench_save","arguments",map("mode","create","data",map("name","denied")),"callId","child-create")).header("Authorization","Bearer platform-service-key-12345678901234567890").header("X-Platform-Mcp-Grant",token)).andExpect(status().isForbidden());}
    @Test void runMetadataNeverIncludesChildManifestsOrConversationInputs()throws Exception{enable("account","nw_task_run_get");ObjectNode run=(ObjectNode)remoteRuns.values().iterator().next();run.putArray("children").add(json.valueToTree(map("id","child","status","completed","manifest",map("instructions",Arrays.asList(map("content","OTHER_EXPERT_PRIVATE"))),"input",map("content","PRIVATE_CONVERSATION"))));JsonNode result=call("nw_task_run_get",map("id",rootTask,"runId",run.path("id").asText()),"run-metadata");assertEquals("child",result.path("data").path("children").path(0).path("id").asText());assertFalse(result.toString().contains("OTHER_EXPERT_PRIVATE"));assertFalse(result.toString().contains("PRIVATE_CONVERSATION"));}
    @Test void delegatedRunsCannotControlOtherExpertExecutions()throws Exception{enable("account","nw_task_run_command");((ObjectNode)remoteRuns.values().iterator().next()).put("parentRunId","root");mvc.perform(postJson("/internal/platform-mcp/execute",map("name","nw_task_run_command","arguments",map("id",rootTask,"runId","another-expert-run","data",map("type","cancel")),"callId","child-control")).header("Authorization","Bearer platform-service-key-12345678901234567890").header("X-Platform-Mcp-Grant",token)).andExpect(status().isForbidden());}
    @Test void memoryProposalsKeepAgentProvenanceAndCannotCreateForeignScopes()throws Exception{enable("account","nw_memory_propose","nw_memory_draft_update");JsonNode result=call("nw_memory_propose",map("kind","project","id",projectId,"data",map("title","可核验偏好","content","测试建议")),"memory-draft");assertEquals("draft",result.path("data").path("state").asText());assertEquals("agent_proposal",result.path("data").path("source").path("type").asText());JsonNode edited=call("nw_memory_draft_update",map("id",result.path("data").path("id").asText(),"data",map("revision",1,"title","编辑建议","content","仍需人工审核")),"memory-edit");assertEquals("draft",edited.path("data").path("state").asText());assertEquals("agent_edit",edited.path("data").path("source").path("type").asText());mvc.perform(postJson("/internal/platform-mcp/execute",map("name","nw_memory_propose","arguments",map("kind","project","id","foreign-project","data",map("title","denied","content","denied")),"callId","foreign-memory")).header("Authorization","Bearer platform-service-key-12345678901234567890").header("X-Platform-Mcp-Grant",token)).andExpect(status().isNotFound());}
    @Test void nestedSchemasRejectReservedFieldsAndInvalidCommands(){assertThrows(RuntimeException.class,()->catalog.validate(catalog.get("nw_runtime_save"),json.valueToTree(map("kind","project","id","p","revision",1,"data",map("mcp",Collections.emptyList())))));assertThrows(RuntimeException.class,()->catalog.validate(catalog.get("nw_task_run_command"),json.valueToTree(map("id","t","runId","r","data",map("type","delete")))));assertThrows(RuntimeException.class,()->catalog.validate(catalog.get("nw_project_list"),json.valueToTree(map("limit",2147483648L))));assertThrows(RuntimeException.class,()->catalog.validate(catalog.get("nw_artifact_import"),json.valueToTree(map("projectId","p","file",map("url","http://untrusted")))));}
    @Test void workflowSchemasMatchActualRevisionAndEnvironmentContracts(){assertDoesNotThrow(()->catalog.validate(catalog.get("nw_workflow_task_command"),json.valueToTree(map("id","task","action","rerun","data",map("expected_version",3,"expected_environment","environment-token","from_steps",Arrays.asList("step"))))));assertDoesNotThrow(()->catalog.validate(catalog.get("nw_workflow_restore"),json.valueToTree(map("id","workflow","path","main.py","data",map("revision_id",7,"expected_revision","revision-hash")))));assertDoesNotThrow(()->catalog.validate(catalog.get("nw_workflow_source_save"),json.valueToTree(map("id","workflow","path","new.py","data",map("content","pass","expected_revision",null)))));assertDoesNotThrow(()->catalog.validate(catalog.get("nw_runtime_save"),json.valueToTree(map("kind","project","id","p","revision",0,"data",map("modelProviderId",null)))));}
}
